"""Build member handoffs, charts, notebooks and findings exclusively from saved results.
Run after method scripts: python -m src.review2_deliverables [--member m2|m5|all].
Notebook outputs are generated by nbconvert, not by this file.
"""
from __future__ import annotations
import argparse,json,html
from pathlib import Path
import numpy as np
import pandas as pd
import nbformat as nbf
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
from src.review2_common import ROOT,TEXT,TS,write_json,study_groups,bootstrap_stat
R=ROOT/'reports/review2'


def notebook(path,title,sections,preserve_before=None):
    nb=nbf.v4.new_notebook();nb.metadata={'kernelspec':{'name':'python3','display_name':'Python 3','language':'python'},'language_info':{'name':'python'}}
    nb.cells=[nbf.v4.new_markdown_cell(title),nbf.v4.new_code_cell("from pathlib import Path\nimport json, pandas as pd\nfrom IPython.display import display, Image\nROOT = next(p for p in [Path.cwd(), *Path.cwd().parents] if (p/'config.yaml').exists())\n")]
    for heading,code in sections:
        nb.cells.append(nbf.v4.new_markdown_cell(heading))
        if code:nb.cells.append(nbf.v4.new_code_cell(code))
    # Keep any cell a co-owner inserted before the marker (e.g. M3 Part A) instead of overwriting it.
    if preserve_before and Path(path).exists():
        src=lambda c: c['source'] if isinstance(c['source'],str) else ''.join(c['source'])
        new_cut=next((i for i,c in enumerate(nb.cells) if src(c).startswith(preserve_before)),None)
        old=nbf.read(path,as_version=4)
        old_cut=next((i for i,c in enumerate(old.cells) if src(c).startswith(preserve_before)),None)
        if new_cut is not None and old_cut is not None:
            nb.cells=old.cells[:old_cut]+nb.cells[new_cut:]
    nbf.write(nb,path)


def handoff(folder,owner,captions):
    pd.DataFrame(captions,columns=['chart','file','takeaway','caveat']).to_csv(folder/'dashboard_captions.csv',index=False)
    schemas={p.name:list(pd.read_csv(p,nrows=0).columns) for p in folder.glob('*.csv')}
    write_json(folder/'dashboard_handoff.json',{'owner':owner,'schemas':schemas,'captions_file':'dashboard_captions.csv',
        'full_parquet_not_for_dashboard':True,'license':'CC BY-SA 4.0; question examples are title + original link only'})


def m5():
    status=json.loads((TS/'run_status.json').read_text())
    if status['status']!='complete':raise RuntimeError('Forecast run not complete')
    metrics=pd.read_csv(TS/'backtest_summary_matched.csv');classes=pd.read_csv(TS/'tag_classes.csv')
    choices=pd.read_csv(TS/'model_choices.csv');fail=pd.read_csv(TS/'fit_failures.csv')
    # Recent history makes the forecast fan readable; full history remains in the CSV.
    history=pd.read_csv(TS/'series_long.csv',parse_dates=['week_start'])
    fc=pd.read_csv(TS/'forecasts_26w.csv',parse_dates=['week_start'])
    recent=history[history.tag.eq('ALL')].tail(26)
    future=fc[fc.tag.eq('ALL') & fc.selected]
    fig,ax=plt.subplots(figsize=(9,4))
    ax.plot(recent.week_start,recent['count'],label='Observed',lw=2)
    ax.plot(future.week_start,future.pred,label='Selected forecast',lw=2,color='#DD7F21')
    ax.fill_between(future.week_start,future.lower95,future.upper95,alpha=.18,label='95% interval')
    ax.fill_between(future.week_start,future.lower80,future.upper80,alpha=.30,label='80% interval')
    ax.set(title='Site total: recent history and forecast to February 2027',ylabel='Questions per week')
    ax.legend(fontsize=10);fig.tight_layout();fig.savefig(TS/'forecast_ALL.png',dpi=160);plt.close(fig)
    coverage=metrics[metrics.model.eq('sarimax')].set_index('horizon')
    fig,ax=plt.subplots(figsize=(8,4))
    for model,g in metrics.groupby('model'):
        if model!='seasonal_naive':ax.plot(g.horizon,g.skill_vs_naive,marker='o',label=model)
    ax.axhline(0,color='gray',lw=.8);ax.set(xticks=[1,4,13,26],xlabel='Weeks ahead',ylabel='Mean skill relative to naive',title='Model skill on identical successful forecast origins');ax.legend();fig.tight_layout();fig.savefig(TS/'backtest_skill.png',dpi=150);plt.close(fig)
    sar=coverage.loc[26];site=classes[classes.tag.eq('ALL')].iloc[0]
    findings=[
        f"Models were selected on 2024 H2 validation; the expanding-window 2025–26 backtest uses first-forecast-week origins spaced four weeks apart.",
        f"On matched origins, SARIMAX's mean 26-week skill versus naive is {sar.skill_vs_naive:.1%}; this is a retrospective model-family comparison, not a new selection from test results.",
        f"Nominal 95% SARIMAX bands cover {sar.coverage95:.1%} of the 26-week endpoints on matched origins: intervals are too narrow for this changing process.",
        f"The validation-selected site model is {site.selected_model}; its week-26 median is {site.forecast_week26:.1f} questions versus {site.last_week_count:.0f} in the last observed week ({site.change_26w_pct:.1f}%). Forecasts end February 23, 2027.",
        f"There are {len(fail)} recorded fit failures. Zero baseline counts cannot support a percentage-change tag class; ITS slope interpretation awaits Akshay's estimates."
    ]
    (R/'m5_findings.md').write_text('# Member 5: forecasting findings\n\n'+'\n'.join('- '+f for f in findings)+'\n\nAssociation is not causation. MASE is scaled forecast error, not percent accuracy.\n')
    handoff(TS,'M5 Adhikkesh',[
        ('Forecast fan','forecast_ALL.png',findings[3],'Prediction intervals are uncertain and empirical coverage is below nominal.'),
        ('Backtest skill','backtest_skill.png',findings[1],'Identical successful origins; nonconverged fits are explicitly reported.'),
        ('Tag classes','tag_classes.csv','Compare forecast decline against each tag’s last observed count.','Zero baseline tags have no defined percent change; ITS inputs pending.')])
    notebook(ROOT/'notebooks/07_timeseries.ipynb', '# Review 2 — Method 1\n\nMember 5: forecasting and evaluation. **Member 3 Part A (STL, stationarity, change points, ITS) is a separate handoff and is not claimed as finished here.**',[
        ('## Part A — Akshay’s pattern analysis\nInsert the reviewed M3 sections here when available.',None),
        ('## Part B — Complete weekly series and fixed evaluation design',"TS = ROOT/'reports/review2/ts'\nstatus=json.loads((TS/'run_status.json').read_text())\nassert status['status']=='complete'\nseries=pd.read_csv(TS/'series_long.csv')\ndisplay(series.groupby('tag').size().rename('weeks').to_frame())\ndisplay(json.loads((TS/'series_manifest.json').read_text()))"),
        ('## Training-only model selection\nOrders use pre-July-2024 AIC; family selection uses 2024 H2. Backtest winners do not choose the final model.',"display(pd.read_csv(TS/'model_choices.csv'))\ndisplay(pd.read_csv(TS/'validation_metrics.csv').head(20))"),
        ('## Four-horizon backtest with three baselines\nMASE uses each origin’s training naive scale. The comparison table uses identical successful origin/horizon cells. Failure records remain visible.',"summary=pd.read_csv(TS/'backtest_summary_matched.csv')\ndisplay(summary)\ndisplay(Image(filename=str(TS/'backtest_skill.png')))\ndisplay(pd.read_csv(TS/'fit_failures.csv'))"),
        ('## Statistical and residual checks\nDM is a paired scaled-error comparison with HAC adjustment; results are exploratory on short overlapping horizons.',"display(pd.read_csv(TS/'diebold_mariano.csv'))\ndisplay(pd.read_csv(TS/'residual_checks.csv'))\ndisplay(Image(filename=str(TS/'acf_ALL.png')))"),
        ('## Forecasts through February 2027\nBands are labelled 80/95%; measured coverage may be much lower. The point is a back-transformed log median.',"fc=pd.read_csv(TS/'forecasts_26w.csv')\ndisplay(fc[fc.selected].groupby('tag').agg(weeks=('horizon','size'),last_date=('week_start','max')))\ndisplay(Image(filename=str(TS/'forecast_ALL.png')))\ndisplay(pd.read_csv(TS/'tag_classes.csv'))"),
        ('## Findings, handoff and remaining dependencies',"print((ROOT/'reports/review2/m5_findings.md').read_text())\ndisplay(json.loads((TS/'dashboard_handoff.json').read_text()))"),
        ('## Optional appendix\nThe GRU and classifier what-if page are stretch items and are not represented as completed analyses.',None)],preserve_before='## Part B')
    write_json(TS/'slide_data.json',{'findings':findings,'summary':metrics.to_dict('records'),'site':site.replace({np.nan:None}).to_dict(),'rows':len(pd.read_csv(TS/'series_long.csv')),
        'tag_groups':{k:list(g.tag) for k,g in classes[classes.tag.ne('ALL')].groupby('forecast_class')}})
    (R/'m5_viva.md').write_text('# Adhikkesh: Review 2 viva\n\n'+
        '- Why MASE? It compares error to the one-step naive error in the training history; smaller is better.\n'+
        '- Why the Review 1 figure changed? The old one-week score was tuned on test weeks and called 100−MAPE accuracy; this evaluation fixes those problems and includes baselines.\n'+
        '- What is an origin? The first forecast week, so all training observations are earlier.\n'+
        '- Why intervals? Point forecasts hide uncertainty; measured coverage shows whether bands are reliable. Our bands under-cover and we report that.\n'+
        '- Did AI cause the change? This observational study shows timing/associations, not proof of cause.\n'+
        '- Why some tags have no class? Percentage change from a last observed count of zero is undefined.\n')
    (R/'contribution_member5.md').write_text('# Member 5 — Adhikkesh\n\nImplemented and ran complete series preparation, training-only ETS/SARIMAX selection, three baselines, four-horizon expanding-window backtests, matched comparisons, DM/residual checks and 26-week forecasts. Generated charts, notebook Part B, handoff schemas/captions and findings. Source: `src/ts_forecast.py`. Evidence: `reports/review2/ts/`, `notebooks/07_timeseries.ipynb`.\n\nPending external input: Akshay’s ITS results for integrated tag interpretation. Optional GRU/what-if/classifier feature extensions are not claimed. No PR, approval or commit is fabricated; link the actual commits and reviews after the owners commit.\n')


def m2():
    stats=json.loads((TEXT/'corpus_stats.json').read_text())
    tone=pd.read_parquet(ROOT/'data/processed/question_tone_v1.parquet')
    g=study_groups(tone);rows=[]
    for tag,s in g.groupby('tag'):
        for name in ['negative','neutral','positive','frustration','politeness']:
            col=s.tone.eq(name).astype(int) if name in ['negative','neutral','positive'] else s[name+'_flag']
            halves=[s.period.eq(p) for p in ['pre','post']]
            values=[float(np.average(col[h],weights=s.loc[h,'sampling_weight'])) for h in halves]
            boots=[bootstrap_stat(col[h],s.loc[h,'sampling_weight'],'mean',1000,42+i) for i,h in enumerate(halves)]
            diff=boots[1]-boots[0]
            rows.append(dict(tag=tag,measure=name,pre=values[0],post=values[1],change=values[1]-values[0],lower95=float(np.quantile(diff,.025)),upper95=float(np.quantile(diff,.975)),bootstrap_resamples=1000))
    trend=pd.DataFrame(rows);trend.to_csv(TEXT/'tone_prepost.csv',index=False)
    q=pd.read_parquet(ROOT/'data/processed/questions_clean_v1.parquet',columns=['question_id','title','created_at','tags','sampling_weight','target_resolved_7d','hours_to_first_answer','hours_to_accept'])
    q['title']=q.title.map(html.unescape);q['link']='https://stackoverflow.com/q/'+q.question_id.astype(str)
    q.to_parquet(ROOT/'data/processed/question_metadata_for_topics.parquet',index=False)
    c=pd.read_csv(TEXT/'complexity_prepost.csv');allc=c[c.tag.eq('ALL')].set_index('metric')
    allt=trend[trend.tag.eq('ALL')].set_index('measure')
    fig,axes=plt.subplots(1,2,figsize=(10,4))
    x=np.arange(3);cats=['negative','neutral','positive']
    axes[0].bar(x-.18,100*allt.loc[cats,'pre'],width=.36,label='Pre');axes[0].bar(x+.18,100*allt.loc[cats,'post'],width=.36,label='Post')
    axes[0].set(xticks=x,xticklabels=cats,ylabel='Weighted share (%)',title='VADER labels — human validation pending');axes[0].legend()
    labels=['Prose words','Code lines'];metrics=['prose_words','code_lines'];x=np.arange(2)
    axes[1].bar(x-.18,allc.loc[metrics,'pre'],width=.36,label='Pre');axes[1].bar(x+.18,allc.loc[metrics,'post'],width=.36,label='Post')
    axes[1].set(xticks=x,xticklabels=labels,ylabel='Weighted median',title='Question text/code grew longer');axes[1].legend();fig.tight_layout();fig.savefig(TEXT/'tone_complexity.png',dpi=150);plt.close(fig)
    fr=allt.loc['frustration'];p=allc.loc['prose_words'];code=allc.loc['code_lines'];multi=allc.loc['multi_technology_flag']
    findings=[f"Prepared {stats['documents_after']:,} prose-only documents; {stats['empty_after_cleaning']:,} are empty after cleaning, and vocabulary contains {stats['vocabulary_size']:,} terms.",
        f"Weighted median prose length changed from {p.pre:.0f} to {p.post:.0f} words; difference {p.change:.0f}, with 95% question-bootstrap interval [{p.lower95:.0f}, {p.upper95:.0f}].",
        f"Weighted median code lines changed from {code.pre:.0f} to {code.post:.0f}; difference {code.change:.0f}, with 95% interval [{code.lower95:.0f}, {code.upper95:.0f}].",
        f"The written frustration-phrase flag changed from {fr.pre:.1%} to {fr.post:.1%}; this is a lexicon measure, not independently verified emotion.",
        f"Questions with at least two study tags changed from {multi.pre:.1%} to {multi.post:.1%}; share-change 95% interval [{100*multi.lower95:.2f}, {100*multi.upper95:.2f}] percentage points."]
    (R/'m2_findings.md').write_text('# Member 2: tone and complexity findings\n\n'+'\n'.join('- '+f for f in findings)+'\n\nVADER accuracy, macro-F1 and rater kappa are pending 200 independent human labels. Do not claim model validation or AI causality from these outputs.\n')
    handoff(TEXT,'M2 Rishiikesh',[
        ('Tone and complexity','tone_complexity.png','Weighted question prose and code medians increased between pre and post periods.','Tone labels are exploratory; human validation pending.'),
        ('Complexity intervals','complexity_prepost.csv',findings[1],'Question bootstrap retains survey weights; transition excluded.'),
        ('Frustration phrases','tone_prepost.csv',findings[3],'Lexicon flags are imperfect proxies, not diagnosed emotion.')])
    notebook(ROOT/'notebooks/08_text_mining.ipynb','# Review 2 — Method 2\n\nMember 2 Part A: corpus, tone, complexity and interpretation. **Member 4 Part B (topics and keywords) is supplied separately. Human labels remain an explicit dependency.**',[
        ('## Corpus preparation and audit',"TEXT=ROOT/'reports/review2/text'\nassert json.loads((TEXT/'corpus_stats.json').read_text())['documents_after']==302026\ndisplay(json.loads((TEXT/'corpus_stats.json').read_text()))\ndisplay(json.loads((TEXT/'text_preprocessing.json').read_text()))\ndisplay(pd.read_parquet(TEXT/'corpus_sample_metadata.parquet').head(8))"),
        ('## Tone on original prose, without code\nTechnical-word overrides are written down; lowercase clean topic text is not used for VADER.',"display(json.loads((TEXT/'tone_method.json').read_text()))\ndisplay(pd.read_csv(TEXT/'tone_monthly.csv').head(10))\ndisplay(pd.read_csv(TEXT/'tone_prepost.csv').query(\"tag == 'ALL'\"))"),
        ('## Independent human validation — pending\nTwo humans label negative/neutral/positive independently, then agree on final labels. No synthetic human labels are generated.',"status=json.loads((TEXT/'tone_validation_status.json').read_text())\ndisplay(status)\ndisplay(pd.read_csv(TEXT/'tone_validation.csv'))\nif status['status']=='complete':\n    display(pd.read_csv(TEXT/'tone_confusion.csv'))\nelse:\n    print('Accuracy, macro-F1 and kappa cannot be reported until all 200 questions have independent labels.')"),
        ('## Complexity and weighted pre/post uncertainty\nFlesch is a prose-reading proxy and technical vocabulary can limit interpretation. Empty prose is not assigned a readability score.',"display(json.loads((TEXT/'complexity_method.json').read_text()))\ndisplay(pd.read_csv(TEXT/'complexity_prepost.csv').query(\"tag == 'ALL'\"))\ndisplay(Image(filename=str(TEXT/'tone_complexity.png')))"),
        ('## Exploratory association with resolution\nWeighted logistic regression controls for full study-tag indicators and year. The coefficients are associations, not causal effects.',"display(pd.read_csv(TEXT/'tone_resolution_association.csv'))"),
        ('## Findings and handoff',"print((ROOT/'reports/review2/m2_findings.md').read_text())\ndisplay(json.loads((TEXT/'dashboard_handoff.json').read_text()))"),
        ('## Part B — Nishanth’s topic models and keywords\nInsert reviewed topic selection, stability, human topic naming and trends here. Rishiikesh can supply topic names only after the topic terms/examples exist.',None)])
    write_json(TEXT/'slide_data.json',{'stats':stats,'findings':findings,'tone':allt.reset_index().to_dict('records'),'complexity':allc.reset_index().to_dict('records'),
        'validation':json.loads((TEXT/'tone_validation_status.json').read_text())})
    (R/'m2_viva.md').write_text('# Rishiikesh: Review 2 viva\n\n'+
        '- Why no code in tone/topics? Code words and identifiers can be mistaken for emotion; topics should describe prose. Code is measured separately for complexity.\n'+
        '- Why overrides? Technical words like fatal/kill/error should not count as negative human emotion by themselves.\n'+
        '- Why weights? Before 2025 sampled questions represent unequal amounts of the population, so weighted summaries preserve the sampling design.\n'+
        '- What is kappa? Agreement between two independent human raters beyond chance; it remains unavailable until both raters label the sample.\n'+
        '- Why bootstrap? Resampling questions with their existing weights estimates uncertainty in medians/share changes.\n'+
        '- What remains? Human tone validation and independent topic naming after M4 supplies topics.\n')
    (R/'contribution_member2.md').write_text('# Member 2 — Rishiikesh\n\nImplemented and ran corpus normalisation and spaCy lemmatisation, title unescaping, technology protection, explicit stopwords, technical-neutral VADER, frustration/politeness flags, weighted monthly summaries, per-question complexity, 1,000-resample pre/post bootstrap intervals, and weighted resolution association with tag/year controls. Source: `src/text_prep.py`, `src/sentiment.py`, `src/complexity.py`. Evidence: `reports/review2/text/`, `notebooks/08_text_mining.ipynb` Part A.\n\nPending: 200 independent M2/M3 human tone labels and M2 topic names after M4 supplies word/example lists. These are not claimed as completed or replaced by AI labels. Add actual commit/PR/reviewer links after the owners commit.\n')

if __name__=='__main__':
    p=argparse.ArgumentParser();p.add_argument('--member',choices=['m2','m5','all'],default='all');a=p.parse_args();R.mkdir(parents=True,exist_ok=True)
    if a.member in ['m5','all']:m5()
    if a.member in ['m2','all']:m2()
